def test_cache_info_half_ratio():
        """AC2: After 2 hits and 2 misses, hit_ratio returns 0.5."""
        cache = Cache(maxsize=10)

        @cached(cache, info=True)
        def func(x):
            return x

        # 2 misses
        func(1)
        func(2)
        # 2 hits
        func(1)
        func(2)

        info = func.cache_info()
        assert info.hits == 2
        assert info.misses == 2
